// モードクリア演出（Ver.1.4.4 試作）
function createCelebrationParticles(container,modeCode){const symbols=modeCode==="A"?["✨","🧭","★","✦"]:modeCode==="M"?["✨","⚡","🥋","✦"]:["✨","🌟","👑","✦","◆"];for(let i=0;i<42;i++){const p=document.createElement("span");p.className="celebration-particle";p.textContent=symbols[i%symbols.length];p.style.left=Math.random()*100+"%";p.style.animationDelay=Math.random()*.9+"s";p.style.animationDuration=2.2+Math.random()*1.8+"s";p.style.fontSize=13+Math.random()*18+"px";container.appendChild(p);}}
function playModeClearEffect(modeCode,options={}){const mode=getModePresentation(modeCode),overlay=document.getElementById("modeClearOverlay"),stage=document.getElementById("modeClearStage"),particles=document.getElementById("celebrationParticles");overlay.style.setProperty("--mode-accent",mode.accent);overlay.style.setProperty("--mode-soft",mode.accentSoft);document.getElementById("modeClearSymbol").textContent=mode.clearSymbol;document.getElementById("modeClearIcon").textContent=mode.icon;document.getElementById("modeClearTitle").textContent=mode.clearTitle;document.getElementById("modeClearMessage").textContent=options.message||mode.clearMessage;document.getElementById("modeClearUnlock").textContent=options.unlockMessage||mode.nextUnlockMessage;document.getElementById("modeClearAction").textContent=options.actionLabel||"つぎへ進む";particles.innerHTML="";createCelebrationParticles(particles,modeCode);stage.classList.remove("animate");void stage.offsetWidth;overlay.classList.remove("hidden");stage.classList.add("animate");}
function closeModeClearEffect(){document.getElementById("modeClearOverlay").classList.add("hidden");}
